// Hand-written. Not generated by Speakeasy.
//
// Covers the migration from v1.3.x state. Lives in the provider package rather
// than alongside the upgraders because the current schema types are injected
// into stateupgraders during this package's init, and stateupgraders cannot
// import provider without a cycle.
//
// TestServiceStateUpgradeFromRealV1317State runs against state genuinely
// written by v1.3.17 (testdata/service_v1317_state.json, captured by importing
// a live service into a v1.3.17 workspace). The hand-built cases alongside it
// cover the branches that capture could not reach, and their shapes come from
// v1.3.17's own schema source rather than from guesswork: d.SetId(apiKey) for
// the service, d.SetId(clientId) plus the separate service_api_key attribute
// for the client.
//
// The full round trip was also verified outside these tests: v1.3.17 state at
// schema_version 0 was placed in front of this provider, and terraform plan
// refreshed cleanly and reported no changes, rewriting the state at version 1
// with api_key carried across as a number and id gone.
package provider

import (
	"context"
	"encoding/json"
	"math/big"
	"os"
	"testing"

	"github.com/authlete/terraform-provider-authlete/internal/stateupgraders"
	"github.com/hashicorp/terraform-plugin-framework/resource"
	"github.com/hashicorp/terraform-plugin-go/tfprotov6"
	"github.com/hashicorp/terraform-plugin-go/tftypes"
)

func schemaTypeOf(t *testing.T, r resource.Resource) tftypes.Type {
	t.Helper()
	return resourceSchema(t, r).Type().TerraformType(context.Background())
}

// runUpgrade feeds raw old state through an upgrader and returns the migrated
// attributes, or the first error diagnostic's summary.
func runUpgrade(t *testing.T, up func(context.Context, resource.UpgradeStateRequest, *resource.UpgradeStateResponse), typ tftypes.Type, old map[string]any) (map[string]tftypes.Value, string) {
	t.Helper()
	raw, err := json.Marshal(old)
	if err != nil {
		t.Fatal(err)
	}
	req := resource.UpgradeStateRequest{RawState: &tfprotov6.RawState{JSON: raw}}
	resp := &resource.UpgradeStateResponse{}
	up(context.Background(), req, resp)

	if resp.Diagnostics.HasError() {
		for _, d := range resp.Diagnostics.Errors() {
			return nil, d.Summary()
		}
	}
	if resp.DynamicValue == nil {
		t.Fatal("upgrader produced neither an error nor a value")
	}
	val, err := resp.DynamicValue.Unmarshal(typ)
	if err != nil {
		t.Fatalf("migrated state does not decode against the current schema: %v", err)
	}
	out := map[string]tftypes.Value{}
	if err := val.As(&out); err != nil {
		t.Fatal(err)
	}
	return out, ""
}

func mustString(t *testing.T, v tftypes.Value) string {
	t.Helper()
	var s string
	if err := v.As(&s); err != nil {
		t.Fatal(err)
	}
	return s
}

// TestServiceStateUpgradeFromV0 is the core case: v1.3.17 kept the service's
// API key in SDKv2's implicit `id` as a string, and this provider models it as
// the Int64 `api_key`.
func TestServiceStateUpgradeFromV0(t *testing.T) {
	typ := schemaTypeOf(t, NewServiceResource())

	out, errSummary := runUpgrade(t, stateupgraders.ServiceStateUpgraderV0, typ, map[string]any{
		"id":           "8689741203439953",
		"service_name": "legacy-service",
		"issuer":       "https://legacy.example.com",

		// Attributes v1.3.17 defined that this provider does not. Each one
		// would fail validation individually; they must all be dropped.
		"jwks_endpoint":                                 "https://legacy.example.com/jwks",
		"iss_response_suppressed":                       true,
		"token_expiration_link":                         true,
		"encryption_alg_req_obj_match":                  true,
		"encryption_enc_alg_req_obj_match":              true,
		"front_channel_encryption_request_obj_required": true,
		"ignore_port_loopback_redirect":                 true,
		"supported_authorization_detail_types":          []string{"payment"},
		"federation_jwk":                                "{}",
		"jwk":                                           "{}",
	})
	if errSummary != "" {
		t.Fatalf("unexpected error: %s", errSummary)
	}

	// The identifier survives, renamed and retyped.
	var apiKey *big.Float
	if err := out["api_key"].As(&apiKey); err != nil {
		t.Fatalf("api_key did not decode as a number: %v", err)
	}
	if got := apiKey.Text('f', 0); got != "8689741203439953" {
		t.Errorf("api_key = %s, want 8689741203439953", got)
	}

	// Ordinary attributes carry across untouched.
	if got := mustString(t, out["service_name"]); got != "legacy-service" {
		t.Errorf("service_name = %q, want %q", got, "legacy-service")
	}

	// And `id` itself is gone, because this provider has no such attribute.
	if _, present := out["id"]; present {
		t.Error("`id` survived the migration; this provider does not define it")
	}
}

// TestClientStateUpgradeFromV0 covers the two-identifier case.
func TestClientStateUpgradeFromV0(t *testing.T) {
	typ := schemaTypeOf(t, NewClientResource())

	out, errSummary := runUpgrade(t, stateupgraders.ClientStateUpgraderV0, typ, map[string]any{
		"id":              "41925176568",
		"service_api_key": "8689741203439953",
		"client_name":     "legacy-client",

		"service_api_secret":         "secret",
		"requestable_scopes":         []string{"read"},
		"requestable_scopes_enabled": true,
		"client_identifier":          "x",
		"jwk":                        "{}",
	})
	if errSummary != "" {
		t.Fatalf("unexpected error: %s", errSummary)
	}

	var clientID *big.Float
	if err := out["client_id"].As(&clientID); err != nil {
		t.Fatalf("client_id did not decode as a number: %v", err)
	}
	if got := clientID.Text('f', 0); got != "41925176568" {
		t.Errorf("client_id = %s, want 41925176568", got)
	}
	if got := mustString(t, out["service_id"]); got != "8689741203439953" {
		t.Errorf("service_id = %q, want the old service_api_key", got)
	}
	if got := mustString(t, out["client_name"]); got != "legacy-client" {
		t.Errorf("client_name = %q, want %q", got, "legacy-client")
	}
}

// TestUpgradeRefusesWithoutIdentifiers: a resource whose identifier cannot be
// recovered must stop with remediation rather than produce state that fails on
// the next refresh with a 403 naming service 0.
func TestUpgradeRefusesWithoutIdentifiers(t *testing.T) {
	for _, tc := range []struct {
		name string
		up   func(context.Context, resource.UpgradeStateRequest, *resource.UpgradeStateResponse)
		typ  func() tftypes.Type
		old  map[string]any
	}{
		{"service without id", stateupgraders.ServiceStateUpgraderV0,
			func() tftypes.Type { return schemaTypeOf(t, NewServiceResource()) },
			map[string]any{"service_name": "x"}},
		{"client without id", stateupgraders.ClientStateUpgraderV0,
			func() tftypes.Type { return schemaTypeOf(t, NewClientResource()) },
			map[string]any{"service_api_key": "123"}},
		// service_api_key was Optional in v1.3.17: left empty the provider fell
		// back to the provider-level api_key, which was never written to state.
		{"client with empty service_api_key", stateupgraders.ClientStateUpgraderV0,
			func() tftypes.Type { return schemaTypeOf(t, NewClientResource()) },
			map[string]any{"id": "123", "service_api_key": ""}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			_, errSummary := runUpgrade(t, tc.up, tc.typ(), tc.old)
			if errSummary == "" {
				t.Error("migration succeeded, but it should have stopped with remediation.\n\n" +
					"Producing state without an identifier is worse than refusing: the next " +
					"refresh calls the API with a null id and fails with an error that does " +
					"not mention migration.")
			}
		})
	}
}

// TestServiceStateUpgradeFromRealV1317State is the one that matters: state
// written by v1.3.17 itself, not a reconstruction. Captured by creating a
// service and importing it into a v1.3.17 workspace, whose read path populates
// state exactly as an apply would.
func TestServiceStateUpgradeFromRealV1317State(t *testing.T) {
	raw, err := os.ReadFile("testdata/service_v1317_state.json")
	if err != nil {
		t.Fatalf("missing captured v1.3.17 state: %v", err)
	}
	var old map[string]any
	if err := json.Unmarshal(raw, &old); err != nil {
		t.Fatal(err)
	}

	// Guards the fixture itself: if it stops looking like v1.3.17 state, the
	// test below would pass for the wrong reason.
	if _, ok := old["id"].(string); !ok {
		t.Fatal("fixture has no string `id`; it is not v1.3.17 state")
	}
	if _, ok := old["api_key"]; ok {
		t.Fatal("fixture already has `api_key`; it is not v1.3.17 state")
	}

	out, errSummary := runUpgrade(t, stateupgraders.ServiceStateUpgraderV0,
		schemaTypeOf(t, NewServiceResource()), old)
	if errSummary != "" {
		t.Fatalf("migrating real v1.3.17 state failed: %s", errSummary)
	}

	var apiKey *big.Float
	if err := out["api_key"].As(&apiKey); err != nil {
		t.Fatalf("api_key did not decode as a number: %v", err)
	}
	if got, want := apiKey.Text('f', 0), old["id"].(string); got != want {
		t.Errorf("api_key = %s, want the old id %s", got, want)
	}
	if _, present := out["id"]; present {
		t.Error("`id` survived the migration")
	}
}
